/// Daily calendar of fixed commitments. Planner sessions are displayed on the
/// plan page; events here define the unavailable time that plan must respect.
class CalendarPage extends ConsumerStatefulWidget { const CalendarPage({super.key}); @override ConsumerState<CalendarPage> createState() => _CalendarPageState(); }
class _CalendarPageState extends ConsumerState<CalendarPage> {
  DateTime _day = DateUtils.dateOnly(DateTime.now());
